Code.NativeIaC:
```bicep
// Enable a system-assigned managed identity on an Azure AI services account
resource account 'Microsoft.CognitiveServices/accounts@2024-10-01' = {
  name: '<example_resource_name>'
  location: '<location>'
  kind: 'OpenAI'
  sku: { name: 'S0' }
  identity: { type: 'SystemAssigned' } // CRITICAL: gives the account an Entra ID identity
  properties: {
    customSubDomainName: '<example_resource_name>'
  }
}
```

Code.Terraform:
```hcl
resource "azurerm_cognitive_account" "<example_resource_name>" {
  name                  = "<example_resource_name>"
  location              = "<location>"
  resource_group_name   = "<resource_group>"
  kind                  = "OpenAI"
  sku_name              = "S0"
  custom_subdomain_name = "<example_resource_name>"

  identity {
    type = "SystemAssigned" # CRITICAL: gives the account an Entra ID identity
  }
}
```
